#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gemver.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix: i = row, j = column (row-major layout)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// All vectors are 1D over 'i'
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta,
                auto A, auto u1, auto v1, auto u2, auto v2,
                auto w, auto x, auto y, auto z) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	std::size_t n = A | get_length<'i'>();
	num_t fn = (num_t)n;

	// Initialize 1D vectors u1, u2, v1, v2, w, x, y, z
	traverser(u1, u2, v1, v2, w, x, y, z).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		u1[state] = (num_t)i;
		u2[state] = ((i + 1) / fn) / (num_t)2.0;
		v1[state] = ((i + 1) / fn) / (num_t)4.0;
		v2[state] = ((i + 1) / fn) / (num_t)6.0;
		y[state]  = ((i + 1) / fn) / (num_t)8.0;
		z[state]  = ((i + 1) / fn) / (num_t)9.0;
		x[state]  = (num_t)0.0;
		w[state]  = (num_t)0.0;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	traverser(A).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			A[state] = (num_t)((i * j) % n) / (num_t)n;
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	#pragma scop
	// First loop:
	// for (i)
	//   for (j)
	//     A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto inner) {
		auto state_i = inner.state(); // contains fixed 'i'
		auto i = get_index<'i'>(state_i);

		inner.template for_each<'j'>([=](auto state) {
			auto j = get_index<'j'>(state);

			// v1 and v2 are 1D over 'i'; use j as their index
			auto v_state = noarr::idx<'i'>(j);

			A[state] = A[state]
				+ u1[state_i] * v1[v_state]
				+ u2[state_i] * v2[v_state];
		});
	});

	// Second loop:
	// for (i)
	//   for (j)
	//     x[i] = x[i] + beta * A[j][i] * y[j];
	traverser(A, x, y).template for_dims<'i'>([=](auto inner) {
		auto state_i = inner.state(); // fixed 'i'
		auto i = get_index<'i'>(state_i);

		inner.template for_each<'j'>([=](auto state) {
			auto j = get_index<'j'>(state);

			// A[j][i]: row = j, column = i
			auto a_state = noarr::idx<'i', 'j'>(j, i);
			auto y_state = noarr::idx<'i'>(j);

			x[state_i] += beta * A[a_state] * y[y_state];
		});
	});

	// Third loop:
	// for (i)
	//   x[i] = x[i] + z[i];
	traverser(x, z).for_each([=](auto state) {
		x[state] += z[state];
	});

	// Fourth loop:
	// for (i)
	//   for (j)
	//     w[i] = w[i] + alpha * A[i][j] * x[j];
	traverser(A, w, x).template for_dims<'i'>([=](auto inner) {
		auto state_i = inner.state(); // fixed 'i'

		inner.template for_each<'j'>([=](auto state) {
			auto j = get_index<'j'>(state);
			auto x_state = noarr::idx<'i'>(j);

			w[state_i] += alpha * A[state] * x[x_state];
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// scalars
	num_t alpha;
	num_t beta;

	// common length settings
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A  = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths);

	auto u1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto v1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto u2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto v2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto w  = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto x  = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto y  = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);
	auto z  = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta,
	           A.get_ref(), u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	           w.get_ref(), x.get_ref(), y.get_ref(), z.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gemver(alpha, beta,
	              A.get_ref(), u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	              w.get_ref(), x.get_ref(), y.get_ref(), z.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, w.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

