		auto i   = get_index<'i'>(s_i);

		// Initialize all 1D arrays at index i
		u1[s_i] = (num_t)i;
		u2[s_i] = (((num_t)i + (num_t)1) / fn) / (num_t)2.0;
		v1[s_i] = (((num_t)i + (num_t)1) / fn) / (num_t)4.0;
		v2[s_i] = (((num_t)i + (num_t)1) / fn) / (num_t)6.0;
		y[s_i]  = (((num_t)i + (num_t)1) / fn) / (num_t)8.0;
		z[s_i]  = (((num_t)i + (num_t)1) / fn) / (num_t)9.0;
		x[s_i]  = (num_t)0.0;
		w[s_i]  = (num_t)0.0;

		// Inner loop over j: initialize row i of A
		trav_i.for_each([=](auto state) {
			auto [ii, j] = get_indices<'i', 'j'>(state);
			A[state] = (num_t)((ii * j) % n) / (num_t)n;
		});
	});
