// computation kernel
// A : i x j
// u1,u2,v1,v2,w,x,y,z : i   (views are renamed as needed)
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A,
                   auto u1, auto v1,
                   auto u2, auto v2,
                   auto w,  auto x,
                   auto y,  auto z) {
	using namespace noarr;

	// Views for vectors conceptually indexed by 'j'
	auto v1_j = v1 ^ noarr::rename<'i', 'j'>();
	auto v2_j = v2 ^ noarr::rename<'i', 'j'>();
	auto y_j  = y  ^ noarr::rename<'i', 'j'>();
	auto x_j  = x  ^ noarr::rename<'i', 'j'>();

	// Transposed view of A: A_t(i,j) == A(j,i)
	auto A_t  = A  ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop

	// A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
	traverser(A, u1, v1_j, u2, v2_j).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			A[state] = A[state]
			         + u1[state] * v1_j[state]
			         + u2[state] * v2_j[state];
		});
	});

	// x[i] = x[i] + beta * A[j][i] * y[j]
	traverser(A_t, x, y_j).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			x[state] = x[state] + beta * A_t[state] * y_j[state];
		});
	});

	// x[i] = x[i] + z[i]
	traverser(x, z).for_each([=](auto state) {
		x[state] = x[state] + z[state];
	});

	// w[i] = w[i] + alpha * A[i][j] * x[j]
	traverser(A, w, x_j).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			w[state] = w[state] + alpha * A[state] * x_j[state];
		});
	});

#pragma endscop
}

