void init_array(num_t &alpha, num_t &beta,
                auto A,
                auto u1, auto v1, auto u2, auto v2,
                auto w,  auto x,  auto y,  auto z) {
	using namespace noarr;

	alpha = static_cast<num_t>(1.5);
	beta  = static_cast<num_t>(1.2);

	auto n  = A | get_length<'i'>();
