		u2[state] = ip1_over_fn / static_cast<num_t>(2.0);
		z[state]  = ip1_over_fn / static_cast<num_t>(9.0);

		x[state] = static_cast<num_t>(0);
		w[state] = static_cast<num_t>(0);
	});

	// Initialize vectors that use index 'j': v1, v2, y
	traverser(v1, v2, y).for_each([=](auto state) {
		auto j = get_index<'j'>(state);

		num_t jp1_over_fn = static_cast<num_t>(j + 1) / fn;

		v1[state] = jp1_over_fn / static_cast<num_t>(4.0);
		v2[state] = jp1_over_fn / static_cast<num_t>(6.0);
		y[state]  = jp1_over_fn / static_cast<num_t>(8.0);
	});

	// Initialize matrix A: A[i][j] = (i*j % n) / n
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = static_cast<num_t>((i * j) % n) / fn;
	});
}

// Computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A,
                   auto u1, auto v1, auto u2, auto v2,
                   auto w,  auto x,  auto y,  auto z) {
	using namespace noarr;

	#pragma scop

	// A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			A[state] = A[state]
			           + u1[state] * v1[state]
			           + u2[state] * v2[state];
		});
	});

	// x[i] = x[i] + beta * A[j][i] * y[j]
	// Create a transposed view of A: A_T[i][j] = A[j][i]
	auto A_T = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

	traverser(x, A_T, y).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			x[state] += beta * A_T[state] * y[state];
		});
	});

	// x[i] = x[i] + z[i]
	traverser(x, z).for_each([=](auto state) {
		x[state] += z[state];
	});

	// w[i] = w[i] + alpha * A[i][j] * x[j]
	traverser(w, A, x).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			w[state] += alpha * A[state] * x[state];
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Scalars
	num_t alpha;
	num_t beta;

	// Length descriptors for dimensions
	auto len_i = noarr::set_length<'i'>(n);
	auto len_j = noarr::set_length<'j'>(n);

	// Allocate data (bags)

	// A: i x j
	auto A  = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ len_i ^ len_j);

	// u1, u2, w, x, z: 1D over 'i'
	auto u1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.u1_layout ^ len_i);
	auto u2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.u2_layout ^ len_i);
	auto w  = noarr::bag(noarr::scalar<num_t>() ^ tuning.w_layout  ^ len_i);
	auto x  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout  ^ len_i);
	auto z  = noarr::bag(noarr::scalar<num_t>() ^ tuning.z_layout  ^ len_i);

	// v1, v2, y: 1D over 'j'
	auto v1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.v1_layout ^ len_j);
	auto v2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.v2_layout ^ len_j);
	auto y  = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout  ^ len_j);

	// Initialize arrays
	init_array(alpha, beta,
	           A.get_ref(),
	           u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	           w.get_ref(),  x.get_ref(),  y.get_ref(),  z.get_ref());

	// Run kernel with timing
	auto start = std::chrono::high_resolution_clock::now();

	kernel_gemver(alpha, beta,
	              A.get_ref(),
	              u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	              w.get_ref(),  x.get_ref(),  y.get_ref(),  z.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output data (to inhibit dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, w.get_ref());
	}

	// Output timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
