                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	// A: i x j
	// u1, u2, w, x, z: i
	// v1, v2, y: j

#pragma scop

	// First loop:
	// for i
	//   for j
	//     A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			A[state] = A[state]
				+ u1[state] * v1[state]
				+ u2[state] * v2[state];
		});
	});

	// Second loop:
	// for i
	//   for j
	//     x[i] = x[i] + beta * A[j][i] * y[j];
	// Use a transposed view of A via rename to swap 'i' and 'j'.
	auto A_T = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

	traverser(A_T, x, y).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			x[state] = x[state] + beta * A_T[state] * y[state];
		});
	});

	// Third loop:
	// for i
	//   x[i] = x[i] + z[i];
	traverser(x, z).template for_each<'i'>([=](auto state) {
		x[state] = x[state] + z[state];
	});

